-- Generated by model/lib/sql/generate.mjs. L1's load of IMPORT Handling Factor from cells/IMPORT Handling Factor.csv in the folder of input cells, into its empty table.
-- Two rows for one cell add up.
-- @csv cells/IMPORT Handling Factor.csv
INSERT INTO "IMPORT Handling Factor" SELECT coalesce(k0."Temperature Zone", fpabench_error('cells name a member Temperature Zone does not have: ' || c."Temperature Zone")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Temperature Zone" k0 ON k0.name = c."Temperature Zone"
GROUP BY 1;
ANALYZE "IMPORT Handling Factor";
